import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"Shape view","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shape.md","filePath":"guide/shape.md","lastUpdated":1791659648000}'),o={name:"guide/shape.md"};function d(n,e,i,l,p,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="shape-view" tabindex="-1">Shape view <a class="header-anchor" href="#shape-view" aria-label="Permalink to &quot;Shape view&quot;">​</a></h1><p>The shape view summarises the structure of your JSON. Switch to it using the <strong>shape</strong> tab in the header (route <code>/schema</code>). Paste JSON into the working editor and the right pane shows an aggregate analysis of the whole document plus the same analysis for every nested object/array shape.</p><h2 id="statistics" tabindex="-1">Statistics <a class="header-anchor" href="#statistics" aria-label="Permalink to &quot;Statistics&quot;">​</a></h2><p>For the whole document and for every nested shape, json-tool reports:</p><table tabindex="0"><thead><tr><th>Statistic</th><th>Meaning</th></tr></thead><tbody><tr><td>Objects</td><td>Total objects in the subtree</td></tr><tr><td>Arrays</td><td>Total arrays in the subtree</td></tr><tr><td>Properties</td><td>Distinct property names</td></tr><tr><td>Values</td><td>Total values (property values plus array elements)</td></tr><tr><td>Filled</td><td>Count of values that are not empty</td></tr><tr><td>Empty</td><td>Count of values that are empty</td></tr><tr><td>Average properties</td><td>Property values per object</td></tr><tr><td>Type breakdown</td><td>Count and percentage for each JSON type, sorted by count</td></tr></tbody></table><p>A value is considered <strong>empty</strong> when it is <code>null</code>, <code>&quot;&quot;</code>, <code>[]</code> or <code>{}</code>.</p><h2 id="nested-shapes" tabindex="-1">Nested shapes <a class="header-anchor" href="#nested-shapes" aria-label="Permalink to &quot;Nested shapes&quot;">​</a></h2><ul><li>Array elements and property values are both counted as values.</li><li>Repeated shapes are aggregated into a single node. For example, 32 objects with an <code>author</code> field produce one <code>author</code> node with an instance count of <code>32</code>.</li><li>A nested shape appears only under its parent path; paths are never duplicated across levels.</li><li>Fields inside an array are measured against the number of elements; nested objects inherit the enclosing population, so percentages never exceed 100%.</li></ul><p>Use <strong>expand all</strong> and <strong>collapse all</strong> to open or close every nested shape at once.</p>',9)])])}const m=t(o,[["render",d]]);export{u as __pageData,m as default};
